    "content": "新华社莫斯科8月21日电 俄罗斯外交部发言人扎哈罗娃21日表示，西方不友好国家的执法机构绕开俄主管机构、直接调查问询俄国内法人的行为，违反俄刑法，俄已针对此种行为修订法律条款。 据俄外交部网站21日发布的消息，扎哈罗娃当天在评论“有不友好国家执法人员向俄罗斯法人发出调查问询要求以获取其‘涉嫌刑事犯罪’的信息”时指出，俄方对这类事件感到担忧。“2022年几乎所有西方国家都单方面削减了与俄罗斯在刑案司法协助方面的合作。现在它们试图绕过俄主管机构办案，这违反了现有相关程序和双多边义务。” 扎哈罗娃提醒说，上述擅自行动会受…"
