    "content": "线上报名失败后，郝文不甘心，又搭高铁去了胖东来新乡和许昌门店。“我是想万一遇见于大哥呢？” 周凯在社交平台留言，争取机会。有网友祝福，有网友反对，“你都不知道他犯什么罪，判五年可不容易”。 “单纯依靠爱心人士很难规模化解决问题。”张荆多次游说各类企业接纳刑释人员，企业普遍顾虑潜在风险，同时也缺少政策激励。 南方周末记者 郑丹 南方周末实习生 黄秋玥 黄渝 责任编辑：谭畅 2026年5月14日，河南许昌，胖东来员工在商场外搬运购物车。视觉中国图 “不一定会要我，但是万一要了呢？” 这几天，周凯没事就打开胖东来商贸集团…"
