    "content": "新华社加德满都8月22日电 特写｜当“国宝”遇见加德满都的童年 新华社记者张平 8月21日下午，尼泊尔中国文化中心迎来一群特殊的“客人”。近200名来自加德满都多所学校的中小学生涌入这里，参加“2026彩绘熊猫巡游记”活动。 “各位小艺术家们——出发吧！”随着主持人一声令下，一直端坐着参加开幕仪式的孩子们像被松开的弹簧，呼啦一下涌向各自心仪的活动区域。 在大熊猫彩绘长卷涂鸦区，10米长的画卷在地面上铺开，黑白轮廓正等待色彩唤醒。数十名学生蹲坐在长卷周围，全神贯注地在长卷上填色。 六年级学生苏普里娅·西尔瓦尔从长卷旁…"
