    "description": "中新网南宁8月22日电(杨志雄 黄智超)近日，走进广西南宁市隆安县城厢镇良兴村阳光玫瑰葡萄产业园，连片标准化种植大棚内绿意盎然、果香四溢。葡萄颗粒饱满、晶莹透亮，宛若串串“绿宝石”缀满枝头。农户们穿梭藤架之间，精准挑选、轻柔采摘、细致分装，田间地头一派繁忙有序的丰收图景。",
