    "title": "字里相逢：沈津、郑培凯书法展在广州举行",
    "link": "https://m.thepaper.cn/detail/33825586",
    "pub_date": "2026-08-22 12:19:06",
    "author": "澎湃讯",
    "description": "“字里相逢——沈津郑培凯书法展”于2026年7月在广州“正空间”举行。沈津、郑培凯两位先生同是1940年代生人，份属好友，同样有着中西文化背景，且学术研究深植于传统中，振笔一挥，迥然不同时流。 沈津先生1945年生于天津，祖籍安徽合肥，沈家是合肥的文化世家，祖父沈曾迈即擅书法，“四体书无所不工”（郑逸梅语），又从吴昌硕学篆，享名于津沪。沈先生幼承祖训，成年后工作于上海图书馆，亲得顾廷龙、潘景郑、瞿凤起等诸老辈指导，学习古籍版本知识，富学…",
    "content": "“字里相逢——沈津郑培凯书法展”于2026年7月在广州“正空间”举行。沈津、郑培凯两位先生同是1940年代生人，份属好友，同样有着中西文化背景，且学术研究深植于传统中，振笔一挥，迥然不同时流。 沈津先生1945年生于天津，祖籍安徽合肥，沈家是合肥的文化世家，祖父沈曾迈即擅书法，“四体书无所不工”（郑逸梅语），又从吴昌硕学篆，享名于津沪。沈先生幼承祖训，成年后工作于上海图书馆，亲得顾廷龙、潘景郑、瞿凤起等诸老辈指导，学习古籍版本知识，富学养、精鉴别，成为学有专攻的版本目录学家。1980年代起，沈先生到美国访学，199…"
