    "author": "张颖哲/央视新闻",
    "description": "总台记者当地时间21日获悉，美国贸易代表格里尔表示，加拿大已拒绝敲定贸易协议。 同一日午夜，加拿大总理卡尼表示，已决定暂停与美国的贸易谈判。 卡尼表示，目前进展不足以实现为加拿大国民设定的目标。他称，在美国对加拿大商品征收50%关税的同时，加拿大将等额征收关税，以保护加拿大的工人和企业。",
    "content": "总台记者当地时间21日获悉，美国贸易代表格里尔表示，加拿大已拒绝敲定贸易协议。 同一日午夜，加拿大总理卡尼表示，已决定暂停与美国的贸易谈判。 卡尼表示，目前进展不足以实现为加拿大国民设定的目标。他称，在美国对加拿大商品征收50%关税的同时，加拿大将等额征收关税，以保护加拿大的工人和企业。"
