    "content": "新华社德国多特蒙德8月21日电（记者赵建通）德甲多特蒙德足球俱乐部首席执行官卡斯滕·克拉默21日在接受国际媒体圆桌采访时表示，俱乐部在引进球员时首先考虑能力，而不是其所带来的市场价值。 近年来，多特蒙德持续拓展亚洲、美洲等海外市场。克拉默表示，一名来自特定国家的球员如果能够在球队取得成功，确实有助于俱乐部加强与当地球迷的联系。他以日本球员香川真司为例说，当俱乐部签下一名优秀的日本、巴西等国球员后，市场部门可以进一步思考如何利用其影响力加强当地传播。 “但我们是一家足球俱乐部，而不是一家营销公司。”克拉默话锋一转，“…"
