    "content": "新华社北京8月22日电 中央气象台22日6时发布台风蓝色预警和暴雨蓝色预警。受第19号台风“紫檀”和西南季风共同影响，预计未来3天华南、浙闽沿海等地有强降雨。8时30分，中国气象局调整暴雨四级应急响应为台风、暴雨四级应急响应。 中央气象台预计，未来3天，海南岛、广西南部、广东、福建、台湾岛、浙江等地部分地区有大到暴雨，局地大暴雨到特大暴雨。此外，四川盆地南部、重庆、湖北中西部、湖南中西部、云南西部、西藏东南部，以及西北地区东部、内蒙古中东部、华北、东北地区等地多分散性阵雨或雷阵雨。 中央气象台22日10时继续发布台…"
