    "description": "荷马（罗马时代仿公元前二世纪希腊化佚名原作所塑） 采访者案：在博尔赫斯的小说《永生》中，罗马军官鲁弗斯在公元二世纪末出发，去寻找永生之城。后来，他又穿越历史各阶段，去找能消除永生的那条河。他1066年为英王或挪威王打过仗，在十三世纪的阿拉伯世界抄过经，1714年为蒲柏的《伊利亚特》英译本交过钱，1729年和维柯对过话。最后，鲁弗斯发觉自己此前的叙述中，已嵌入很多荷马史诗的零散诗句。最后的最后，鲁弗斯发现自己就是荷马本人。“我曾经是荷马；…",
    "content": "荷马（罗马时代仿公元前二世纪希腊化佚名原作所塑） 采访者案： 在博尔赫斯的小说《永生》中，罗马军官鲁弗斯在公元二世纪末出发，去寻找永生之城。后来，他又穿越历史各阶段，去找能消除永生的那条河。他1066年为英王或挪威王打过仗，在十三世纪的阿拉伯世界抄过经，1714年为蒲柏的《伊利亚特》英译本交过钱，1729年和维柯对过话。最后，鲁弗斯发觉自己此前的叙述中，已嵌入很多荷马史诗的零散诗句。最后的最后，鲁弗斯发现自己就是荷马本人。“我曾经是荷马；不久，我像尤利西斯一样，我将是无人。”不仅如此，曾经和鲁弗斯为伴的穴居人阿尔戈…"
