    "content": "这是2026年8月1日在甘肃省张掖市肃南县境内拍摄的祁连山景色（无人机照片）。 初秋的祁连山北麓，草原风光美如画。 沿牧道穿行，低矮云杉覆盖的山坡出现在眼前。这里原来是有40多年开采历史的甘肃省武威市天祝藏族自治县千马龙煤矿。站在山坡俯瞰，昔日裸露的矿井边坡、堆渣场重新披绿。 一处矿山旧址的重生，映照着祁连山生态环境由乱到治、由治及美的深刻变迁。 作为我国西部重要的生态安全屏障，祁连山局部生态破坏问题一度十分突出。对此，习近平总书记曾多次作出重要指示，要求坚决整改。 甘肃痛定思痛，一边狠抓生态问题整改治理，一边加速…"
