    "content": "2026年08月22日 本报北京8月21日电&nbsp;&nbsp;（记者王云杉、靳博）8月21日，我国自主研发的新一代深水多功能海洋工程船“海洋石油292”在江苏南通启东市完工交付。该船由中国海油旗下海洋石油工程股份有限公司投资建造，进一步提升了我国水下工程和海洋在役设施专业服务能力，为加快深海能源资源开发提供了关键装备保障。 该船采用双层结构、单体流线型设计，总长126米、型宽28米，排水量超1.76万吨，具备深水级海洋工程开发、建设、维护、检修及应急处置等多项能力，适配多海域水下管缆及结构物安装、海底调查、运…"
