    "description": "2026年08月22日 据新华社电 （记者罗毓）欧洲航天局11日在官网发布公报说，一个国际天文学家团队通过分析美国詹姆斯·韦布空间望远镜2025年的观测数据发现，在银河系中心超大质量黑洞附近一颗处于演化晚期的恒星周围存在水和富氧尘埃。这一发现表明，即使处于强烈辐射环境中，演化晚期的恒星仍可持续向周围空间释放形成恒星和行星所需的物质。 研究团队此次重点观测的是恒星IRS 3。研究人员利用韦布空间望远镜的中红外仪器分析了IRS 3发出的红外…",
    "content": "2026年08月22日 据新华社电&nbsp;&nbsp;（记者罗毓）欧洲航天局11日在官网发布公报说，一个国际天文学家团队通过分析美国詹姆斯·韦布空间望远镜2025年的观测数据发现，在银河系中心超大质量黑洞附近一颗处于演化晚期的恒星周围存在水和富氧尘埃。这一发现表明，即使处于强烈辐射环境中，演化晚期的恒星仍可持续向周围空间释放形成恒星和行星所需的物质。 研究团队此次重点观测的是恒星IRS 3。研究人员利用韦布空间望远镜的中红外仪器分析了IRS 3发出的红外光，发现富氧尘埃的明显特征，并首次在该恒星周围的包层中明确…"
