    "content": "2026年08月22日 据新华社电&nbsp;&nbsp;（记者谭晶晶、罗毓）美国航空航天局18日表示，国际空间站两名宇航员当天完成历时6个多小时的太空行走任务，旨在为空间站更换地空通信天线。由于作业耗时超出预期，替换天线在此次太空行走中未被安装。 两名出舱宇航员分别为美航空航天局的阿尼尔·梅农和欧洲航天局的索菲·阿德诺。据介绍，梅农和阿德诺拆除了一副发生故障的地空通信天线，并将其长期固定在国际空间站桁架结构上。由于断开电缆和松开螺栓所需时间超出预期，宇航员未能按原计划安装替换天线。相关安装工作预计将在下一次太空行…"
