    "author": "",
    "description": "2026年08月22日 尚玉平供图 \"> 2022年，新疆文物考古研究所、吐鲁番学研究院联合对高昌故城以北的巴达木东墓群进行了抢救性发掘，共清理墓葬11座，出土文物及考古发现具有重构西域历史图景、补证文献记载缺环、深化边疆治理体系与文化交融研究等多重学术意义。 该墓群位于新疆吐鲁番市火焰山镇巴达木村，是一处唐代中后期墓葬遗存。形制较为统一，均坐北朝南，平面呈“刀”形。墓葬规模普遍较大，通长21—28米，深4.5—7.3米，由墓道、过洞、…",
    "content": "2026年08月22日 金银平脱花鸟纹铜镜。 尚玉平供图 \"> 2022年，新疆文物考古研究所、吐鲁番学研究院联合对高昌故城以北的巴达木东墓群进行了抢救性发掘，共清理墓葬11座，出土文物及考古发现具有重构西域历史图景、补证文献记载缺环、深化边疆治理体系与文化交融研究等多重学术意义。 该墓群位于新疆吐鲁番市火焰山镇巴达木村，是一处唐代中后期墓葬遗存。形制较为统一，均坐北朝南，平面呈“刀”形。墓葬规模普遍较大，通长21—28米，深4.5—7.3米，由墓道、过洞、天井、甬道、东西耳室和墓室组成。墓内葬1—2人，置于“U”…"
