    "title": "08版 - 器物也在讲述工匠的双手",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202608/22/content_30176457.html",
    "pub_date": "2026-08-22 08:26:03",
    "author": "",
    "description": "2026年08月22日 资料图片 \"> 站在殷墟妇好墓出土的青铜器面前，厚重的器壁、繁密的纹饰和庄严的王室气象扑面而来。仿佛凝固的历史证词在诉说：3000多年前的商王朝，已经拥有高度发达的青铜文明。可是，如果把目光移到腹内壁、附件接合处、残留的泥芯和断裂面等不易被看到的地方——另一段历史便会慢慢显露出来。 有些青铜器的内壁留着凸起的“铆头”。它们不是装饰，而是后铸留下的痕迹。工匠先铸成器身，预留孔道，再把器耳、提手或盖钮接上，重新浇入铜…",
    "content": "2026年08月22日 殷墟妇好墓出土青铜鸮尊。 资料图片 \"> 站在殷墟妇好墓出土的青铜器面前，厚重的器壁、繁密的纹饰和庄严的王室气象扑面而来。仿佛凝固的历史证词在诉说：3000多年前的商王朝，已经拥有高度发达的青铜文明。可是，如果把目光移到腹内壁、附件接合处、残留的泥芯和断裂面等不易被看到的地方——另一段历史便会慢慢显露出来。 有些青铜器的内壁留着凸起的“铆头”。它们不是装饰，而是后铸留下的痕迹。工匠先铸成器身，预留孔道，再把器耳、提手或盖钮接上，重新浇入铜液。铜液穿过孔洞，在器壁内侧凝结，把附件牢牢锁住。这种…"
