    "content": "新华网天津8月22日电 题：船舶海工，转型升级把握“深蓝”新机遇 新华网记者邵香云 梁姊 赵子硕 不久前，中船天津船舶有限公司（简称“大船天津”）一日内迎来“一船交付、一船开工”两大生产节点：甲醇双燃料15000标准箱（TEU）集装箱船提前23天命名交付、7100标准箱（TEU）环保型集装箱船正式开工建造。 “截至目前，公司手持订单近500亿元，已交付的船舶中绿色燃料船舶占比超过大半。”大船天津副总经理姜春光说。 作为海洋经济重点产业，我国船舶和海工装备业发展向好。工信部数据显示，今年1-6月我国造船完工量、新接订…"
