    "content": "钟才文 今年以来，在以习近平同志为核心的党中央坚强领导下，各地区各部门积极作为、迎难而上，有效应对各种外部冲击和内部困难，扎扎实实推动高质量发展，我国经济运行呈现出动能向新、结构向优的发展态势，成绩可圈可点。上半年，宏观指标总体稳健，国内生产总值（GDP）增长4.7%、在全球主要经济体中继续位居前列，物价合理回升，就业总体稳定，国际收支基本平衡。同时，规模以上工业企业利润增长18.7%，全国一般公共预算收入增长4.7%，一些经营主体经济效益得到改善。 当前，中国经济正处在新旧动能加快转换和发展方式转变的关键时期。观…"
