    "content": "新华社华盛顿8月21日电（记者黄强 徐剑梅）据美国媒体21日报道，美国政府已通知国会计划向联合国支付8.5亿美元，以偿还其拖欠的部分联合国会费及其他款项。 据美联社获得的本月提交给国会议员的通知显示，美国务院计划拨付7.25亿美元用于支付联合国会费，1.25亿美元用于支持联合国在海地和刚果（金）的维和行动。 报道说，美国拖欠联合国相关摊款资金总额约50亿美元，其中包括超20亿美元会费和约30亿美元的维和行动经费。 今年1月30日，联合国秘书长古特雷斯的副发言人哈克说，古特雷斯已致信所有联合国会员国，警示联合国“面临…"
