    "content": "新华社巴西利亚8月21日电（记者吴昊）巴西总统卢拉21日与美国总统特朗普通电话，反对美国政府近期对巴西商品加征关税。 据巴西政府发布的声明，在1小时20分钟的通话中，卢拉和特朗普讨论了双边贸易、公共安全合作及国际热点问题。卢拉指出，近期美国对巴西加征关税的相关指控缺乏依据，这些关税措施对巴美两国均构成损害，双方应继续通过对话协商解决分歧。 美国贸易代表办公室7月15日宣布自7月22日起对部分巴西产品在原有关税基础上加征25%的关税。7月23日，美国贸易代表办公室又以所谓“强迫劳动”为由，对包括巴西在内的数十个国家和…"
